    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address other, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(other != address(this));
        require(other != address(c));
        require(amount > 0);
        require(address(this).balance >= amount);

        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint cBalanceBefore = address(c).balance;
        uint myCredit = amount;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        uint cBalanceAfter = address(c).balance;

        assert(cBalanceBefore - cBalanceAfter == myCredit);
    }

    receive() external payable {}
}

